// MavModeFlag represents MAV_MODE_FLAG bitfield values.
// These flags can be combined using bitwise OR operations.
// Reference: https://mavlink.io/en/messages/common.html#MAV_MODE_FLAG
type MavModeFlag int32

const (
	MavModeFlag_MAV_MODE_FLAG_UNSPECIFIED MavModeFlag = 0
	// Bit 0 (1): Custom mode is enabled
	MavModeFlag_MAV_MODE_FLAG_CUSTOM_MODE_ENABLED MavModeFlag = 1
	// Bit 1 (2): Test mode enabled
	MavModeFlag_MAV_MODE_FLAG_TEST_ENABLED MavModeFlag = 2
	// Bit 2 (4): Autonomous mode enabled
	MavModeFlag_MAV_MODE_FLAG_AUTO_ENABLED MavModeFlag = 4
	// Bit 3 (8): Guided mode enabled
	MavModeFlag_MAV_MODE_FLAG_GUIDED_ENABLED MavModeFlag = 8
	// Bit 4 (16): Stabilize mode enabled
	MavModeFlag_MAV_MODE_FLAG_STABILIZE_ENABLED MavModeFlag = 16
	// Bit 5 (32): Hardware in the loop simulation enabled
	MavModeFlag_MAV_MODE_FLAG_HIL_ENABLED MavModeFlag = 32
	// Bit 6 (64): Manual input is enabled
	MavModeFlag_MAV_MODE_FLAG_MANUAL_INPUT_ENABLED MavModeFlag = 64
	// Bit 7 (128): Safety switch is currently engaged (armed)
	MavModeFlag_MAV_MODE_FLAG_SAFETY_ARMED MavModeFlag = 128
)

